from produire import produire,paras,table,steps
from medicaments import ciproxin_hc
parts=[
('L’otite externe aiguë bactérienne atteint la peau du conduit auditif. Les {limites anatomiques} la distinguent de l’infection située derrière le tympan.',paras('Le tableau associe douleur, inflammation du conduit et parfois écoulement ou baisse auditive par obstruction. Une rougeur isolée ne suffit pas à attribuer toute l’otalgie à une infection bactérienne.')),
('Humidité et microtraumatismes favorisent cette affection. Les {contextes à rechercher} comprennent baignade, manipulation et dispositifs auriculaires.',paras('Cotons-tiges, grattage et embouts peuvent altérer la peau du conduit. Diabète, immunodépression et radiothérapie régionale modifient le risque de complication et la stratégie de soins.')),
('L’altération de la barrière cutanée facilite la prolifération bactérienne. Les {mécanismes douloureux} expliquent une douleur importante dans un conduit étroit.',paras('L’œdème distend les tissus et peut obstruer le conduit, réduisant aussi la pénétration des gouttes. Une infection qui dépasse la peau du conduit doit être distinguée d’une forme superficielle simple.')),
('Rechercher une extension et une otite nécrosante. Les {signes d’alarme} exigent un avis urgent.',paras('Douleur profonde nocturne ou disproportionnée, granulations, déficit facial ou autre nerf atteint, tuméfaction importante et altération générale imposent une évaluation spécialisée. Le seuil de vigilance est particulièrement bas chez le diabétique ou l’immunodéprimé.')),
('L’entretien précise douleur au toucher, prurit et écoulement. Les {questions thérapeutiques} identifient les facteurs d’échec ou de risque.',paras('Demander baignade, nettoyage, traitement déjà instillé, allergie, prothèse auditive, chirurgie, drain et perforation connue. La formulation exacte des gouttes importe davantage que la seule molécule annoncée.')),
('Une douleur à la pression du tragus ou à la mobilisation du pavillon est évocatrice. Les {éléments otoscopiques} confirment l’atteinte du conduit et évaluent le tympan.',paras('Décrire œdème, érythème, sécrétions et visibilité tympanique. Nettoyer seulement avec une méthode adaptée et sous contrôle ; l’absence de visibilité ne prouve pas l’intégrité du tympan.')),
('Toutes les inflammations du conduit ne sont pas bactériennes. Le {diagnostic différentiel} évite de répéter un antibiotique inefficace.',table(['Indice','Alternative'],[['Prurit dominant, débris fongiques.','Otomycose.'],['Récidive liée à un produit ou un embout.','Dermatite ou allergie de contact.'],['Vésicules et paralysie faciale.','Zona otique.'],['Tympan bombé ou écoulement provenant d’une perforation.','Otite moyenne.'],['Douleur persistante profonde avec granulations.','Otite nécrosante ou lésion tumorale.']])) ,
('Le diagnostic d’une forme simple est principalement clinique. Les {critères de cohérence} associent symptômes récents et inflammation du conduit.',paras('Une douleur au tragus isolée n’exclut pas une maladie associée. Le terrain, l’état du tympan et l’absence de signe invasif déterminent si la prise en charge peut rester locale.')),
('Le bilan microbiologique dépend du contexte et de la préparation retenue. Les {indications d’examens} sont renforcées en cas d’échec ou de gravité.',paras('Un prélèvement peut être utile en cas de récidive, résistance suspectée, immunodépression ou échec. Ciproxin HC demande un test de sensibilité dans son information professionnelle. Une suspicion d’invasion nécessite biologie et imagerie spécialisées.')),
('L’{arbre de traitement} part du tympan et de l’extension. L’accès du médicament à la peau malade doit être assuré.',steps('Écarter une forme invasive ou étendue.', 'Déterminer si le tympan est intact et si le conduit permet l’administration.', 'Choisir soins locaux et préparation compatible ; un nettoyage ou une mèche peuvent nécessiter l’ORL.', 'Réexaminer si absence d’amélioration en 48–72 heures, et immédiatement si aggravation.')),
('Une forme non compliquée relève généralement d’un traitement local et d’une antalgie adaptée. Les {restrictions de préparation} empêchent de transposer une prescription à tout tympan.',paras('Les antibiotiques systémiques sont réservés aux indications liées à l’extension, au terrain ou à l’impossibilité de traitement local efficace. Le schéma ci-dessous concerne exclusivement la préparation et l’indication citées.', '@@MEDICAMENTS@@')),
('La {prévention} réduit humidité et blessures du conduit. Les habitudes de nettoyage doivent être discutées sans instrumentation domestique.',paras('Éviter grattage et coton-tige, limiter l’entrée d’eau pendant le traitement et entretenir les embouts. Une récidive impose de rechercher dermatose, obstacle, allergie ou exposition persistante.')),
('Conduit inflammatoire et douleur au tragus orientent le diagnostic. Le tympan conditionne le choix des gouttes. L’échec à 48–72 heures impose un nouvel examen. Douleur profonde et terrain à risque font rechercher une invasion.','')]
quiz=[('Où siège l’infection ?','Dans la peau du conduit auditif externe.'),('Quel geste provoque souvent la douleur ?','Pression du tragus ou mobilisation du pavillon.'),('Une baisse auditive signifie-t-elle toujours atteinte cochléaire ?','Non : le conduit peut être obstrué ; il faut néanmoins évaluer la nature de la baisse.'),('Un tympan non visible est-il intact ?','On ne peut pas le conclure.'),('Toute otite externe nécessite-t-elle un antibiotique oral ?','Non.'),('Un prurit persistant après gouttes évoque quoi ?','Notamment mycose, dermatite ou allergie.'),('Quelle douleur inquiète chez un diabétique ?','Une douleur profonde, nocturne ou disproportionnée.'),('Les granulations imposent-elles une réévaluation ?','Oui, notamment pour invasion ou tumeur.'),('Ciproxin HC convient-il en cas de perforation supposée ?','Non.'),('Quelle dose de cette préparation figure dans l’AIPS dès deux ans ?','Trois gouttes deux fois par jour pendant sept jours.'),('Quel examen la notice mentionne-t-elle avant ce traitement ?','Un test de sensibilité.'),('Le schéma de cette préparation traite-t-il une otite moyenne ?','Non.'),('Quand réévaluer si l’amélioration manque ?','En 48 à 72 heures, plus tôt si aggravation.'),('Le coton-tige prévient-il les récidives ?','Non : il peut traumatiser et entretenir le problème.')]
produire(1,parts,quiz,(1,3,16,21),ciproxin_hc)
